def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform rows and columns are the separators; their color varies by task.
    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ]

    row_edges = [-1] + divider_rows + [h]
    col_edges = [-1] + divider_cols + [w]

    # The object color is the non-background, non-separator color.
    colors = {v for row in grid for v in row}
    sep_colors = {grid[r][0] for r in divider_rows}
    sep_colors |= {grid[0][c] for c in divider_cols}
    background = max(colors - sep_colors, key=lambda v: sum(row.count(v) for row in grid))

    obj_colors = colors - sep_colors - {background}
    obj = max(obj_colors, key=lambda v: sum(row.count(v) for row in grid))

    out = []
    for ri in range(len(row_edges) - 1):
        out_row = []
        for ci in range(len(col_edges) - 1):
            r0, r1 = row_edges[ri] + 1, row_edges[ri + 1]
            c0, c1 = col_edges[ci] + 1, col_edges[ci + 1]
            count = sum(grid[r][c] == obj
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            out_row.append(1 if count >= 2 else background)
        out.append(out_row)
    return out
